import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.D45daZFh.js";const p=JSON.parse('{"title":"成人高血压食养指南（2023年版）","description":"国家卫健委《成人高血压食养指南（2023年版）》要点导读：限盐、增钾、控制体重，附分地区分季节食谱示例。","frontmatter":{"title":"成人高血压食养指南（2023年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2023年版","published":"2023-01","document_no":"国卫办食品函〔2023〕5号","source_url":"https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml","status":"现行","tags":["高血压","食养","限盐","饮食指导"],"reviewed":false,"description":"国家卫健委《成人高血压食养指南（2023年版）》要点导读：限盐、增钾、控制体重，附分地区分季节食谱示例。"},"headers":[],"relativePath":"guides/hypertension-2023.md","filePath":"guides/hypertension-2023.md"}'),s={name:"guides/hypertension-2023.md"};function n(i,t,d,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="成人高血压食养指南-2023年版" tabindex="-1">成人高血压食养指南（2023年版） <a class="header-anchor" href="#成人高血压食养指南-2023年版" aria-label="Permalink to &quot;成人高血压食养指南（2023年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml" target="_blank" rel="noreferrer">通知及原文入口</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人高血压患者，以及血压偏高、有高血压家族史或生活方式风险较高的人群及其家人。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li><strong>限盐是第一位的</strong>：控制每日食盐摄入，并留意酱油、咸菜、加工食品里的&quot;隐性盐&quot;。</li><li><strong>增加钾摄入</strong>：多吃新鲜蔬菜水果等富钾食物，平衡钠的影响。</li><li><strong>吃动平衡、控制体重</strong>：超重者减重本身就有助于降压。</li><li><strong>戒烟限酒、规律作息</strong>：膳食调整与生活方式干预并重。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>指南按<strong>不同地区、不同季节</strong>给出了食谱示例——翻到对应章节，参考离家最近的地区、当下季节的搭配即可，不必照搬某一天的完整食谱。具体数值与食谱以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2023 年版（现行）</td></tr><tr><td>印发时间</td><td>2023 年 1 月（具体日期待核对原文）</td></tr><tr><td>发文字号</td><td>国卫办食品函〔2023〕5号（待人工复核）</td></tr></tbody></table>',11)])])}const _=e(s,[["render",n]]);export{p as __pageData,_ as default};
